import{_ as t,o as r,c as i,ah as s}from"./chunks/framework.DDXs_i7t.js";const u=JSON.parse('{"title":"Press Release: The Horten Mystery Goes Live!","description":"","frontmatter":{},"headers":[],"relativePath":"en/logbuch/pressemitteilung.md","filePath":"en/logbuch/pressemitteilung.md"}'),o={name:"en/logbuch/pressemitteilung.md"};function a(n,e,l,c,p,h){return r(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="press-release-the-horten-mystery-goes-live" tabindex="-1">Press Release: The Horten Mystery Goes Live! <a class="header-anchor" href="#press-release-the-horten-mystery-goes-live" aria-label="Permalink to &quot;Press Release: The Horten Mystery Goes Live!&quot;">​</a></h1><p><strong>For Immediate Release.</strong></p><p><strong>Subject:</strong> <em>A New Era of Digital Mockumentary.</em></p><p>Today, the official documentation website for the film project <strong>&quot;The Horten Mystery&quot;</strong> went live. This unique project combines investigative research with satirical storytelling to illuminate the legacy of Heidi and Helmut Horten.</p><p><strong>Key Features of the Project:</strong></p><ul><li><strong>AI-Powered Creation:</strong> Documented and developed with the help of Gemini CLI.</li><li><strong>Top-Tier Cast:</strong> Featuring August Diehl, Birgit Minichmayr, and Oliver Masucci.</li><li><strong>Transmedia Approach:</strong> A mix of screenplay drafts, research archives, and artistic reflections.</li></ul><p>The public is invited to follow the creation process in real-time. &quot;The Horten Mystery&quot; is more than a film; it is an experiment in digital transparency and political satire.</p><p><em>Contact: Volti Sodala (Project Lead).</em></p>',8)])])}const d=t(o,[["render",a]]);export{u as __pageData,d as default};
